    "1_status_bar_check": {
      "goal": "Confirm you’re attached to a fast network and have strong signal.",
      "how_to_check": [
        "Look at the very top of your screen (status bar). Tell me:",
        "- Network type indicator next to the signal bars (e.g., 5G, 4G/LTE, 3G, 2G/E).",
        "- Approximate signal strength (how many bars out of 4 or 5).",
        "- Whether you see any of these icons: ✈️ (Airplane Mode), a small ‘R’ or roaming indicator, a key icon (VPN), a down-arrow/Data Saver icon."
      ],
      "alternative": "If you prefer, you can use your phone’s diagnostic: check_status_bar and share the results."
    },
    "2_enable_device_data_roaming": {
      "goal": "Allow data while abroad.",
      "steps_android": [
        "Settings > Network & Internet (or Connections) > Mobile network (or SIMs).",
        "Turn ON Data roaming."
      ],
      "note": "Roaming is already enabled on your line from my side. This ensures your phone also permits roaming."
    },
    "3_make_sure_mobile_data_is_on": {
      "steps_android": [
        "Settings > Network & Internet > SIMs/Mobile network > Mobile data: ON."
      ]
    },
    "4_set_network_mode_to_4g_5g_preferred": {
      "goal": "Use the fastest available network.",
      "steps_android": [
        "Settings > Network & Internet > Mobile network > Preferred network type.",
        "Select 4G/5G preferred (or 5G/4G/LTE auto). Avoid 2G/3G options."
      ]
    },
    "5_turn_off_data_saver": {
      "steps_android": [
        "Settings > Network & Internet > Data Saver: OFF."
      ]
    },
    "6_check_vpn_and_airplane_mode": {
      "vpn": "If you see a key icon or know a VPN is ON, temporarily disconnect it.",
      "airplane_mode": "Ensure Airplane Mode is OFF."
    },
    "7_speed_test": {
      "goal": "Verify performance after the above changes.",
      "how": "Run run_speed_test on your phone and tell me the reported result (Excellent/Good/Fair/Poor/etc.).",
      "expectation": "We’re aiming for Excellent. Anything less and I’ll keep tuning."
    }
  },
  "next_if_not_excellent": [
    "We’ll check APN settings: use check_apn_settings and report the APN name and whether MMSC is set. If incorrect/missing, we’ll reset_apn_settings and then reboot_device (required for changes to apply).",
    "If needed, we can also try switching network mode temporarily to 4G-only to improve stability, then test again."
  ],
  "questions_for_you": [
    "After enabling device Data Roaming and confirming the settings above, what network type shows in your status bar (5G/4G/3G/2G)?",
    "How many signal bars do you see?",
    "Do you see a roaming ‘R’, a VPN key, or a Data Saver icon?",
    "What’s the result of the speed test now?"
  ],
  "note": "If service doesn’t improve within a couple of minutes after turning roaming on at the device level, we’ll continue with APN and other targeted checks. I’m staying with you step-by-step until we reach Excellent."
}

