messages.content:
{
  "acknowledgement": "Yes—please turn Airplane Mode OFF now. That’s the primary reason you had no data or signal.",
  "what_i_already_did": [
    "Enabled international data roaming on your line from our side.",
    "Verified you have ~6.3 GB remaining this cycle on your Premium Plan (15 GB total)."
  ],
  "step_by_step_actions_now": [
    {
      "step": 1,
      "action": "Turn OFF Airplane Mode",
      "how": [
        "Swipe down the quick settings shade and tap the airplane icon so it is NOT highlighted, OR",
        "Settings > Network & Internet (or Connections) > Airplane Mode: OFF"
      ],
      "reason": "Airplane Mode disables all cellular radios, so no signal/data can work.",
      "after_do_this": "Wait 30–60 seconds for the phone to register on a network. Watch for signal bars and a network type (5G/4G/LTE) and an ‘R’ for roaming."
    },
    {
      "step": 2,
      "action": "Ensure Mobile Data is ON",
      "how": [
        "Settings > Network & Internet > Mobile network (or SIMs) > Mobile data: ON"
      ],
      "reason": "Required for internet over cellular."
    },
    {
      "step": 3,
      "action": "Enable Data Roaming on device",
      "how": [
        "Settings > Network & Internet > Mobile network (or SIMs) > Data roaming: ON"
      ],
      "reason": "You’re in France; the device must allow data while roaming.",
      "note": "Roaming is already enabled on your line from my side."
    },
    {
      "step": 4,
      "action": "Set Preferred Network Type to 4G/5G",
      "how": [
        "Settings > Network & Internet > Mobile network > Preferred network type > 5G/4G (LTE) Auto or 4G/5G preferred"
      ],
      "reason": "Ensures the phone uses the fastest available network for Excellent speed."
    },
    {
      "step": 5,
      "action": "Turn OFF Data Saver",
      "how": [
        "Settings > Network & Internet > Data Saver: OFF"
      ],
      "reason": "Prevents background/data throttling that can feel like very slow internet."
    },
    {
      "step": 6,
      "action": "Temporarily disconnect any VPN",
      "how": [
        "If you see a key icon or know a VPN is connected, disconnect it in the VPN app or in Settings > Network & Internet > VPN."
      ],
      "reason": "Some VPNs can severely reduce speed, especially while roaming."
    },
    {
      "step": 7,
      "action": "Run a speed test",
      "how": [
        "Use your phone’s run_speed_test and share the result (Excellent/Good/Fair/Poor) along with the measured network type and bars."
      ],
      "reason": "We’re targeting an Excellent result. If it’s not Excellent, I’ll continue tuning."
    }
  ],
  "what_to_report_back": [
    "Network type now shown (5G/4G/LTE/3G/2G).",
    "How many signal bars you see.",
    "Whether an ‘R’ (roaming), a key (VPN), or a Data Saver icon is present.",
    "Speed test result."
  ],
  "if_not_excellent_next_steps": [
    "Toggle Mobile Data OFF then ON once, wait 20 seconds, test again.",
    "Check APN: we’ll use check_apn_settings; if MMSC/APN look wrong, we’ll reset_apn_settings and then reboot_device (required).",
    "Try 4G-only temporarily for stability if 5G is flaky, then re-test."
  ],
  "note": "After turning Airplane Mode OFF and enabling device data roaming, it may take up to 1–2 minutes for the phone to fully register on a roaming partner. I’ll stay with you step-by-step until we reach Excellent."
}

