{
  "summary": "You have strong 5G signal and fresh data, but the speed test shows No Connection. That usually means the phone’s data session isn’t establishing—commonly due to APN/VPN/Data Saver/roaming toggles.",
  "why_this_happens": [
    "Even with 5G bars, if APN settings are wrong or stale, data won’t pass.",
    "A connected VPN or Data Saver can block or stall traffic.",
    "Roaming/data toggles sometimes need a refresh after Airplane Mode."
  ],
  "do_this_next_in_order": [
    {
      "step": 1,
      "action": "Quick refresh of data/roaming",
      "instructions": [
        "toggle_data: Turn Mobile Data OFF, wait 5 seconds, then ON.",
        "toggle_roaming: Turn Data Roaming OFF, wait 5 seconds, then ON.",
        "Wait 15–30 seconds for the network to register."
      ],
      "reason": "Forces a fresh data session while roaming."
    },
    {
      "step": 2,
      "action": "Confirm no VPN and Data Saver",
      "instructions": [
        "check_vpn_status: If a VPN is connected, use disconnect_vpn.",
        "check_data_restriction_status: If Data Saver is ON, use toggle_data_saver_mode to turn it OFF."
      ],
      "reason": "VPN/Data Saver can block or throttle mobile data."
    },
    {
      "step": 3,
      "action": "Verify network mode",
      "instructions": [
        "check_network_mode_preference: Ensure it’s 4g_5g_preferred. If not, set_network_mode_preference to 4g_5g_preferred."
      ],
      "reason": "Ensures the device stays on fast networks."
    },
    {
      "step": 4,
      "action": "Verify APN and reset if needed",
      "instructions": [
        "check_apn_settings: Look at APN name and status.",
        "If APN looks incorrect/blank, use reset_apn_settings.",
        "After resetting APN, use reboot_device to restart the phone."
      ],
      "reason": "Incorrect or stale APN is a common cause of No Connection despite strong signal."
    }
  ],
  "then_test": [
    "Run run_speed_test on mobile data (Wi‑Fi off) and tell me the result label.",
    "Also share what you see in the status bar (bars and 5G/LTE/4G) after the steps."
  ],
  "if_still_no_connection_after_apn_reset_and_reboot": [
    "reseat_sim_card: Reseat the SIM, then reboot_device again.",
    "check_network_status: Confirm Mobile Data ON and Roaming ON.",
    "Try a different spot outdoors briefly to rule out a local micro‑coverage issue."
  ],
  "account_side_status": [
    "Roaming on your line: Enabled.",
    "Data: +2 GB added successfully; service should be available this cycle."
  ],
  "request": "Please go through steps 1–4 in order, then run the speed test and share the result label plus any observations from the status bar. I’ll advise next steps immediately based on what you see."
}

