  "step_1_confirm_sim_status": {
    "why": "If the SIM now shows Active (not Missing/Locked), we can focus on registration/settings.",
    "instructions": "On your Galaxy S21: Settings > About phone > Status > SIM card status. Please tell me exactly what it shows (Active/Missing/Locked)."
  },
  "step_2_network_mode": {
    "why": "If the phone is set to an older mode or got stuck on a bad band, it may not register.",
    "instructions": [
      "Go to Settings > Connections > Mobile networks > Network mode.",
      "Select 5G/LTE/3G/2G (Auto) if available.",
      "Wait 60 seconds. If still no bars, switch temporarily to LTE/3G/2G (Auto) for 60 seconds, then switch back to 5G/LTE/3G/2G (Auto)."
    ]
  },
  "step_3_operator_selection": {
    "why": "Forcing a fresh network scan often fixes registration.",
    "instructions": [
      "In Settings > Connections > Mobile networks > Network operators:",
      "Turn OFF “Select automatically.” Wait for the scan to complete.",
      "From the list, choose our carrier. If it fails or says ‘can’t connect,’ turn ON “Select automatically” again."
    ]
  },
  "step_4_mobile_data_and_radio_refresh": {
    "why": "Data being OFF won’t hide signal bars, but enabling it and refreshing radios can nudge registration.",
    "instructions": [
      "Ensure Mobile data is ON: Settings > Connections > Data usage > Mobile data (turn ON).",
      "Toggle Airplane mode ON for 30 seconds, then OFF."
    ]
  },
  "step_5_location_check": {
    "why": "If it’s a local coverage dead spot, you may register in a different spot.",
    "instructions": [
      "If possible, move near a window or step outside for 2–3 minutes.",
      "If you can, try a different nearby location (another room or outside your building)."
    ]
  },
  "step_6_cross_test_isolation": {
    "why": "This isolates whether the issue is the SIM or the phone’s SIM reader/radio.",
    "instructions": [
      "If available: insert your SIM into another unlocked phone to see if it gets signal.",
      "Or insert a known‑good SIM (from a friend/family) into your Galaxy S21 to see if it shows bars."
    ],
    "interpretation": [
      "If your SIM works in another phone: likely a phone hardware/settings issue on the S21.",
      "If another SIM works in your S21: likely an issue with your SIM card.",
      "If neither works in your S21: likely a hardware/radio issue on the S21.",
      "If your SIM doesn’t work in any phone: likely a faulty/damaged SIM."
    ]
  },
  "optional_interim_relief": {
    "wifi_calling": {
      "why": "Lets you place/receive calls over Wi‑Fi while we troubleshoot cellular.",
      "instructions": "Settings > Connections > Wi‑Fi Calling > turn ON (if available)."
    }
  },
  "what_to_report_back": [
    "SIM status now (Active/Missing/Locked).",
    "Results of Network mode and Operator selection changes (any errors or whether it connects).",
    "Whether moving locations changed anything.",
    "Any cross‑test results (SIM in another phone or another SIM in your S21)."
  ],
  "next_if_unresolved": "If after these steps you still have no signal and the SIM shows Active, we may be looking at a device radio/SIM reader issue or a SIM that needs replacement. In that case, I can arrange a handoff to a human agent to assist with SIM replacement options or advanced device diagnostics.",
  "reassurance": "I’m here with you—let’s run these quick checks and we’ll take the appropriate next step based on what we find."
}

