  "do_this_now": [
    {
      "step": "Confirm the messaging app can send MMS",
      "actions": [
        "Run can_send_mms and tell me the result and any message it shows."
      ],
      "why": "This quickly tells us if the app sees any blocking condition."
    },
    {
      "step": "Ensure the messaging app has the SMS permission",
      "actions": [
        "Run check_app_permissions with app_name=\"messaging\".",
        "If \"sms\" is NOT listed as granted, run grant_app_permission with app_name=\"messaging\" and permission=\"sms\".",
