      "then_check": "Does the status bar now show any signal bars or a network type (5G/4G/LTE/3G)? Is Mobile Data still shown as disabled?"
    },
    {
      "step": 2,
      "title": "Enable Mobile Data",
      "do": [
        "Turn Mobile Data ON in your phone’s settings."
      ],
      "then_check": "Do you now see the mobile data icon and a network type (5G/4G/LTE/3G)? Try loading a simple website (example.com)."
    },
    {
      "step": 3,
      "title": "Check SIM status",
      "do": [
        "Open your phone’s SIM settings and check SIM status."
      ],
      "what_to_note": "Is the SIM shown as Active, Missing, or Locked?",
      "if_missing": "Power off the phone, remove and reinsert the SIM (reseat it), then power back on.",
      "if_locked": "Do not guess the PIN/PUK. Tell me it shows Locked and I’ll escalate for SIM security assistance."
    },
    {
      "step": 4,
      "title": "Reseat the SIM anyway (helps even if status looks OK)",
      "do": [
        "Power off the phone.",
        "Remove the SIM tray, reinsert the SIM carefully, and ensure it’s snug.",
        "Power the phone back on."
      ],
      "then_check": "After boot, do you now have signal bars and a network type?"
    },
    {
      "step": 5,
      "title": "Ensure modern Network Mode",
      "do": [
