{
  "summary": "You now have excellent 5G and working mobile data. Since MMS still fails after an APN reset and reboot, the most likely blockers are the messaging app’s permissions/settings. We’ll verify those next, then run a quick MMS diagnostic. If that still fails, I’ll escalate for a backend MMS provisioning check.",
  "thought_process": "MMS depends on mobile data (which is fine now). When MMS still won’t send, the common causes are: missing app permissions (Storage/Photos/Media and SMS), app-level data restrictions, or a backend provisioning issue for MMS on the line. We’ll eliminate the app-side causes first.",
  "steps": [
    {
      "step": 1,
      "title": "Check messaging app permissions",
      "do": [
        "Open Settings on your phone.",
        "Find your default messaging app (e.g., Messages).",
        "Open Permissions and ensure these are Allowed: Storage/Photos & Media and SMS (and optionally Contacts)."
      ],
      "then_try": "Go back to the messaging app and try sending a small photo MMS to yourself with Wi‑Fi OFF.",
      "why": "Without Storage/Photos/SMS, the app may not attach or send media."
    },
    {
      "step": 2,
      "title": "Allow background data for the messaging app",
      "do": [
        "In Settings > Apps > Messaging app > Mobile data or Data usage, ensure Background data is allowed and there are no app-specific data restrictions."
      ],
      "then_try": "Attempt the MMS again (still with Wi‑Fi OFF).",
      "why": "MMS often uses background data to send/receive."
    },
    {
      "step": 3,
      "title": "Run an MMS capability check",
      "do": [
        "Use your phone’s MMS diagnostic (can_send_mms) if available and share the result (pass/fail or any error).",
        "Alternatively, try attaching a small photo and sending to your own number to simulate the same check."
      ],
      "why": "Confirms whether the messaging stack reports MMS is ready to send with current settings."
    },
    {
      "step": 4,
      "title": "Optional isolation test (if you have another messaging app installed)",
      "do": [
        "If there’s another SMS/MMS app already installed on your phone, set it as default temporarily and try sending an MMS."
      ],
      "why": "Helps determine if the issue is specific to your current messaging app."
    }
  ],
  "please_reply_with": [
    "Which permissions were missing (if any) and whether you enabled them.",
    "Whether background data for the messaging app was allowed.",
    "The result of the MMS diagnostic (can_send_mms) or the test send.",
    "If you tried another messaging app, did the MMS send there?"
  ],
  "next_if_still_failing": "If permissions and background data are OK and the diagnostic still fails, I will escalate to a human agent to check MMS provisioning on your line."
}

