messages.content:
{
  "intent": "technical_support_mms",
  "reasoning": "Great—service and data are back on 5G with excellent signal, so the remaining blockers for MMS are usually APN/MMSC configuration, Wi‑Fi Calling interference, Data Saver/VPN restrictions, or messaging app permissions. We’ll verify and fix these in order.",
  "step_by_step": [
    {
      "step": "Confirm mobile data is actually working now",
      "why": "MMS needs any working mobile data.",
      "do": [
        "With Wi‑Fi OFF, try opening a couple of websites/apps that use data.",
        "If browsing fails, tell me right away."
      ]
    },
    {
      "step": "Quick MMS diagnostic",
      "why": "Confirms the device’s MMS capability status.",
      "do": [
        "Run can_send_mms and share the result."
      ]
    },
    {
      "step": "Check APN and MMSC",
      "why": "A missing or incorrect MMSC URL is a very common MMS failure cause.",
      "do": [
        "Run check_apn_settings and share the APN name and whether an MMSC URL is shown.",
        "If MMSC is missing or looks blank/incorrect: run reset_apn_settings, then run reboot_device, wait for 5G to return, and test MMS again."
      ]
    },
    {
      "step": "Check Wi‑Fi Calling",
      "why": "Depending on configuration, Wi‑Fi Calling can interfere with MMS when on mobile data or roaming.",
      "do": [
        "Run check_wifi_calling_status.",
        "If it shows ON: run toggle_wifi_calling to turn it OFF temporarily, then try sending an MMS again."
      ]
    },
    {
      "step": "Check Data Saver/Background restrictions",
      "why": "Data Saver can block background data that MMS may rely on.",
      "do": [
        "Run check_data_restriction_status.",
        "If Data Saver is ON or background data is restricted: run toggle_data_saver_mode to turn it OFF, then retry MMS."
      ]
    },
    {
      "step": "Check VPN",
      "why": "A VPN can sometimes block or slow MMS traffic.",
      "do": [
        "Run check_vpn_status.",
        "If a VPN is connected: run disconnect_vpn, then retry MMS."
      ]
    },
    {
      "step": "Verify messaging app permissions",
      "why": "The app needs Storage and SMS permissions to send/receive MMS media.",
      "do": [
        "Run check_app_permissions with app_name=\"messaging\".",
        "If Storage or SMS permissions are missing: run grant_app_permission for each missing one (\"storage\" and/or \"sms\").",
        "Retry sending an MMS."
      ]
    }
  ],
  "what_to_report_back": [
    "Whether browsing works with Wi‑Fi OFF.",
    "Result of can_send_mms.",
    "From check_apn_settings: APN name and whether MMSC is present.",
    "Wi‑Fi Calling status (and if you turned it OFF).",
    "Data Saver status (and if you turned it OFF).",
    "VPN status (and if you disconnected it).",
    "Messaging app permissions list."
  ],
  "next_if_still_failing_after_all_above": [
    "We’ll re-run APN reset + reboot if MMSC was corrected and verify again.",
    "If everything looks correct and MMS still fails, I’ll escalate to a human agent for further provisioning checks."
  ],
  "notes": "You already have roaming enabled on your line and 2 GB refueled; once APN/MMSC and the above settings are correct, MMS should send normally on 4G/5G."
}

