messages.content:
{
  "reassurance": "You’re okay—this is common and usually easy to fix. Your phone just isn’t detecting the SIM right now. We’ll try a safe SIM reseat/refresh and then check the signal again.",
  "why_this_happened": "When Airplane Mode was ON, the cellular radio was off. After turning it off, the phone should reconnect. If it still shows No Signal and says the SIM is missing/not working, the SIM may just need to be reseated or the eSIM line toggled back on.",
  "very_small_steps": [
    {
      "step": "Power the phone OFF",
      "details": "Hold the power button (and volume button on some phones) and slide/tap to power off. Wait 10 seconds."
    },
    {
      "step": "Decide if you have a physical SIM tray or eSIM",
      "how_to_tell": [
        "Physical SIM tray: Look along the phone’s edge for a tiny hole next to a thin outline—this is the tray. If you see this, follow the Physical SIM steps.",
        "No tray visible (especially on some newer iPhones in the U.S.): you likely use eSIM. Follow the eSIM steps."
      ]
    }
  ],
  "physical_sim_path": {
    "title": "If you have a physical SIM tray",
    "steps": [
      "Use a SIM tool or a small paperclip to gently press into the tiny hole; the tray will pop out.",
      "Remove the SIM, check the gold contacts for dust, gently wipe with a soft cloth (no liquids), and reinsert it in the same orientation so it sits flat.",
      "Push the tray back in fully so it’s flush.",
      "Power the phone back ON and wait up to 2 minutes for signal.",
      "Check the top bar for signal bars and 4G/LTE/5G (you might also see an “R” for roaming)."
    ],
    "safety_note": "Be gentle; don’t force the tray. This won’t delete any data."
  },
  "esim_path": {
    "title": "If you use eSIM (no tray)",
    "steps": [
      "Power the phone back ON.",
      "iPhone: Settings > Cellular (or Mobile Data). Under SIMs, tap your plan. Make sure “Turn On This Line” is ON. If it’s already ON, toggle it OFF, wait 10 seconds, then toggle back ON.",
      "Android: Settings > Network & Internet (or Connections) > SIMs/SIM manager. Ensure your carrier SIM is enabled. If enabled, toggle OFF, wait 10 seconds, then toggle ON.",
      "Wait up to 2 minutes for the phone to register with a local network in France.",
      "Check the top bar for bars and 4G/LTE/5G (and possibly an “R”)."
    ]
  },
  "then_enable_data": {
    "title": "Turn on Mobile Data and Data Roaming (since you’re in France)",
    "steps": [
      "iPhone: Settings > Cellular > Cellular Data: ON. Then Cellular Data Options > Data Roaming: ON.",
      "Android: Settings > Network & Internet (or Connections) > Mobile network > Mobile data: ON, Data roaming: ON."
    ],
    "what_to_expect": "“Data Disabled” should disappear, and you should see 4G/LTE/5G next to the bars."
  },
  "quick_test": [
    "With Wi‑Fi still OFF, try loading example.com in your browser.",
    "If it loads, try sending a photo to your own number."
  ],
  "important_signals_to_tell_me": [
    "If the phone asks for a SIM PIN/PUK after reseating or toggling the line—please stop and tell me. I’ll get you to a human agent to securely help with SIM unlock.",
    "If after reseating/toggling and waiting 2 minutes it still shows No SIM/No Service, tell me exactly what the top bar says."
  ],
  "questions_for_you": [
    "Do you see a SIM tray on the phone’s edge, or does it look eSIM-only?",
    "After following the appropriate path, what does the top bar show now (bars, 4G/LTE/5G, an ‘R’, or still No Signal)?",
    "Did “Data Disabled” go away after turning Mobile Data and Data Roaming ON?"
  ],
  "my_thought_process": "Your line on our side is active with roaming and plenty of data. The phone reporting SIM missing/no service is the blocker. Reseating a physical SIM or toggling the eSIM line typically restores detection. Once the phone sees the SIM and registers on a French network, enabling data and roaming should let MMS work again."
}

