{
  "reassurance": "Great progress—seeing bars means the SIM is being detected now. The two things we need to fix are: (1) Data is turned OFF on the phone (“Data Disabled”), and (2) you’re on 2G, which is too slow for MMS. We’ll turn data ON and switch your phone to 4G/5G. I’ll guide you in tiny steps.",
  "why_this_step": "MMS needs mobile data. 2G is not suitable for MMS, so we’ll enable data and set the phone to prefer 4G/5G.",
  "step_1_turn_mobile_data_on": {
    "iphone": [
      "Open Settings.",
      "Tap Cellular (or Mobile Data).",
      "Turn Cellular Data ON."
    ],
    "android": [
      "Open Settings.",
      "Tap Network & Internet (or Connections) > Mobile network.",
      "Turn Mobile data ON."
    ],
    "what_to_look_for": "“Data Disabled” should disappear soon after this."
  },
  "step_2_enable_data_roaming": {
    "why": "You’re in France; the phone must allow roaming for data to work abroad.",
    "iphone": [
      "Settings > Cellular > Cellular Data Options.",
      "Turn Data Roaming ON."
    ],
    "android": [
      "Settings > Network & Internet (or Connections) > Mobile network.",
      "Turn Data roaming ON."
    ]
  },
  "step_3_set_network_mode_to_4g_5g": {
    "why": "2G is too slow for MMS. We want 4G/LTE or 5G.",
    "iphone": [
      "Settings > Cellular > Cellular Data Options > Voice & Data.",
      "Select 5G Auto (or 5G On). If 5G isn’t available, choose LTE."
    ],
    "android": [
      "Settings > Network & Internet (or Connections) > Mobile network > Preferred network type.",
      "Select 5G/4G (may be called 5G/4G/3G/2G auto or LTE/5G preferred)."
    ]
  },
  "step_4_check_status_bar": {
    "what_to_expect": [
      "Bars plus 4G/LTE/5G (you may also see an “R” for roaming).",
      "Confirm that “Data Disabled” is gone."
    ],
    "if_still_2g": [
      "Wait up to 60–90 seconds; move near a window/outdoors.",
      "If it still shows 2G after setting the network mode, briefly toggle Airplane Mode ON for 10 seconds, then OFF to refresh the connection."
    ]
  },
  "quick_tests_after_you_see_4g_lte_5g": [
    "With Wi‑Fi OFF, open your browser and go to example.com. Does it load?",
    "Send a small photo to your own number. Does it send?"
  ],
  "what_to_reply_with": [
    "Did “Data Disabled” disappear after turning Mobile Data ON?",
    "What does the top bar show now (2G/3G/H+/4G/LTE/5G, any “R”)?",
    "Did example.com load with Wi‑Fi OFF?",
    "Did the photo to yourself send?"
  ],
  "my_thought_process": "Your account has roaming enabled and plenty of data. The phone-side settings are the blockers: data is OFF and the network mode is stuck on 2G. Enabling data, allowing roaming, and preferring 4G/5G should restore mobile data and allow MMS to send."
}

