{
  "reassurance": "You’ve done all the right things so far. Since you now have full bars, 5G, and fast internet, the remaining common blockers for MMS are phone-side settings we can fix. We’ll go step by step and keep it simple.",
  "thought_process": "With data working, MMS usually fails due to either Wi‑Fi Calling interference or an APN (MMSC) setting issue in the phone. We’ll first check Wi‑Fi Calling, then reset the APN to defaults and reboot, which fixes most roaming‑MMS issues.",
  "next_steps": [
    {
      "step": "Temporarily turn OFF Wi‑Fi Calling (quick, reversible)",
      "iphone": [
        "Settings > Cellular > Wi‑Fi Calling.",
        "Turn Wi‑Fi Calling OFF (just for testing)."
      ],
      "android": [
        "Settings > Network & Internet (or Connections) > Mobile network (or SIMs).",
        "Find Wi‑Fi Calling and turn it OFF (temporarily)."
      ],
      "why": "Some networks don’t handle MMS over Wi‑Fi Calling while abroad."
    },
    {
      "step": "Reset APN settings to default, then reboot the phone",
      "iphone": [
        "Settings > Cellular (or Mobile Data) > Cellular Data Network (if present).",
        "Use the option to Reset/Restore the APN to default.",
        "Now fully power the phone OFF, wait 10 seconds, then power it ON."
      ],
      "android": [
        "Settings > Network & Internet (or Connections) > Mobile network > Access Point Names (APN).",
        "Open the menu (⋮ or three dots) and tap Reset to default (or Restore defaults).",
        "Now fully power the phone OFF, wait 10 seconds, then power it ON."
      ],
      "why": "MMS needs a correct MMSC in the APN. Resetting to defaults and rebooting applies the right values."
    },
    {
      "step": "After reboot: confirm required toggles",
      "actions": [
        "Make sure Mobile Data is ON.",
        "Make sure Data Roaming is ON (you’re in France).",
        "Keep Wi‑Fi OFF just for this test."
      ],
      "expect": "Top bar should show bars plus 4G/LTE/5G (possibly an “R” for roaming)."
    },
    {
      "step": "Test MMS again",
      "actions": [
        "Open your browser and confirm example.com loads quickly (with Wi‑Fi OFF).",
        "Send a small photo to your own number. Note exactly what happens (sending, spinning, failed)."
      ]
    }
  ],
  "if_still_fails_after_above": [
    {
      "step": "Check the messaging app’s permissions",
      "iphone": [
        "Settings > Privacy & Security > Photos: ensure your Messages app has access (All Photos or at least Selected).",
        "Settings > Messages: ensure MMS Messaging is ON."
      ],
      "android": [
        "Settings > Apps > [Your Messages app] > Permissions.",
        "Allow Storage/Photos and SMS permissions."
      ],
      "why": "Without storage/SMS permissions or MMS toggle, media messages can fail."
    },
    {
      "step": "Turn OFF Data Saver and any VPN",
      "actions": [
        "Data Saver OFF: Settings > Network & Internet > Data Saver: OFF.",
        "VPN OFF: Settings > Network & Internet > VPN: disconnect."
      ],
      "why": "Data Saver/VPN can interfere with MMS delivery."
    }
  ],
  "questions_for_you": [
    "Were you able to turn Wi‑Fi Calling OFF?",
    "Did you find the APN screen and reset it, then reboot?",
    "After rebooting and confirming Data and Roaming are ON, what does the top bar show now?",
    "When you try sending a photo to yourself after these steps, does it send or still fail? If it fails, does it show any new message or just spin/fail?"
  ],
  "note": "If during any step your phone asks for a SIM PIN/PUK, please stop and tell me right away so I can arrange secure help. Otherwise, take these one by one and let me know exactly what you see—I’ll adjust the next step based on your results."
}

