messages.content:
{
  "acknowledgement": "You’re doing great—this is normal after turning Airplane Mode off. Radios sometimes need a moment to re-register, and Airplane Mode can leave mobile data and device-side roaming turned off.",
  "what_to_do_next": [
    {
      "step": "Give it a moment",
      "action": "Wait 60–90 seconds to let the phone re-register on the local network.",
      "why": "After airplane mode, the phone needs to find a partner network in France."
    },
    {
      "step": "Turn ON Mobile Data",
      "action": "Run toggle_data until it indicates Mobile Data is ON.",
      "why": "MMS needs mobile data. Your line has data again and roaming is enabled on our side."
    },
    {
      "step": "Turn ON Data Roaming (on the phone)",
      "action": "Run toggle_roaming until it indicates Roaming is ON.",
      "why": "You’re abroad; the device must allow roaming in addition to us enabling it on the account."
    },
    {
      "step": "Keep Wi‑Fi OFF for the test",
      "action": "Run toggle_wifi until Wi‑Fi shows OFF.",
      "why": "We want to test cellular data only."
    },
    {
      "step": "Check current status",
      "action": "Run check_status_bar and check_network_status and tell me exactly what they show (signal bars, network type like 4G/LTE/5G vs 2G/E, Mobile Data state, Roaming state).",
      "why": "This confirms you’re on a suitable network with data and roaming enabled."
    }
  ],
  "if_no_signal_after_steps": [
    {
      "step": "Optimize network mode",
      "action": [
        "Run check_network_mode_preference.",
        "If it shows 2G/3G or similar, run set_network_mode_preference with mode \"4g_5g_preferred\"."
      ],
      "why": "2G/3G can be unreliable for data/MMS abroad; 4G/5G preferred usually connects better."
    },
    {
      "step": "Check SIM card status",
      "action": [
        "Run check_sim_status.",
        "If it says Missing, run reseat_sim_card, then run check_sim_status again.",
        "If it says Locked (PIN/PUK), stop and tell me—I'll get you to a human to unlock safely."
      ],
      "why": "If the SIM isn’t detected or is locked, the phone can’t get service."
    },
    {
      "step": "Move for better signal",
      "action": "If possible, go near a window or outdoors and re-run check_status_bar.",
      "why": "Buildings can block roaming signals."
    },
    {
      "step": "Reboot to refresh registration",
      "action": "Run reboot_device, then wait 1–2 minutes and re-run check_network_status.",
      "why": "Forces a clean network re-registration after enabling data/roaming."
    }
  ],
  "then_test_mms": "After you see signal and Mobile Data + Roaming ON, try sending a picture message. If it doesn’t send immediately, wait ~60 seconds and try again.",
  "what_to_send_me": [
    "The outputs of check_network_status and check_status_bar after turning Mobile Data and Roaming ON.",
    "What happened when you tried to send the MMS."
  ],
  "reassurance": "You won’t break anything by toggling these settings. If any step is confusing, tell me exactly what you see and I’ll guide you one tap at a time."
}

