      "step": "Reseat the SIM (safe and reversible)",
      "action": "Run reseat_sim_card.",
      "why": "This simulates removing/reinserting the SIM or refreshing the eSIM profile so the phone can detect it again."
    },
    {
      "step": "If you have a physical SIM (optional manual check)",
      "action": [
        "Power the phone OFF.",
        "Use the SIM tool/paperclip to eject the tray.",
        "Gently remove the SIM, check for dust/debris, and reinsert it in the same orientation so it sits flat and snug.",
        "Reinsert the tray fully and power the phone ON."
      ],
      "tips": "Avoid bending the SIM; don’t force the tray."
    },
    {
      "step": "Re-check after reseat",
      "action": [
        "Run check_sim_status again.",
        "If it shows Active, proceed to the next steps.",
        "If it still shows Missing, run reboot_device, wait 1–2 minutes after restart, and run check_sim_status again.",
