messages.content:
{
  "acknowledgement": "Nice work getting the phone onto 5G with data and roaming ON. Since MMS still won’t send, the most common remaining causes are APN/MMSC settings, Wi‑Fi Calling conflicts, VPN interference, Data Saver restrictions, or the messaging app lacking permissions.",
  "my_thought_process": "MMS depends on mobile data plus a correct MMSC server in your APN. With strong 5G confirmed, we’ll verify the phone-side settings that specifically affect MMS and fix anything off. Each step below is safe and reversible.",
  "please_do_these_in_order": [
    {
      "step": "Quick MMS diagnostic",
      "action": "Run can_send_mms",
      "why": "This tells us if the phone’s messaging stack thinks MMS can be sent right now.",
      "what_to_share": "Paste the result."
    },
    {
      "step": "Verify APN/MMSC",
      "action": "Run check_apn_settings",
      "why": "A missing or incorrect MMSC URL will block MMS even when data works.",
      "what_to_share": "Tell me what it shows for APN name and MMSC URL.",
      "fix_if_needed": [
        "If MMSC is missing/incorrect: run reset_apn_settings",
        "Then run reboot_device",
        "After the reboot, test sending an MMS again"
      ]
    },
    {
      "step": "Check Wi‑Fi Calling",
      "action": "Run check_wifi_calling_status",
      "why": "Some setups fail to send MMS when Wi‑Fi Calling is ON.",
      "fix_if_needed": [
        "If it shows ON: run toggle_wifi_calling to turn it OFF",
        "Test MMS again"
      ]
    },
    {
      "step": "Check for VPN interference",
      "action": "Run check_vpn_status",
      "why": "An active VPN can block/slow MMS traffic.",
      "fix_if_needed": [
        "If a VPN is connected: run disconnect_vpn",
        "Test MMS again"
      ]
    },
    {
      "step": "Disable Data Saver if enabled",
      "action": "Run check_data_restriction_status",
      "why": "Data Saver can interfere with background data MMS needs.",
      "fix_if_needed": [
        "If it shows Data Saver ON: run toggle_data_saver_mode to turn it OFF",
        "Test MMS again"
      ]
    },
    {
      "step": "Confirm messaging app permissions",
      "action": "Run check_app_permissions for your messaging app (the default one you’re using)",
      "why": "The app needs storage and sms permissions to send/attach photos.",
      "fix_if_needed": [
        "If storage is not granted: run grant_app_permission with permission \"storage\"",
        "If sms is not granted: run grant_app_permission with permission \"sms\"",
        "Test MMS again"
      ]
    },
    {
      "step": "Confirm data works in general (optional but helpful)",
      "action": "Run run_speed_test",
      "why": "Verifies the phone truly has working mobile data on 5G. Any result above 'no connection' is good for MMS.",
      "what_to_share": "Paste the speed test result."
    }
  ],
  "reminders": [
    "Keep Wi‑Fi OFF during these tests so we’re only testing cellular data.",
    "You already have 2 GB refueled and roaming enabled on your line, so once APN/MMSC and app/device settings are right, MMS should send."
  ],
  "what_to_send_me": [
    "Results of can_send_mms and check_apn_settings (especially the MMSC URL).",
    "Whether Wi‑Fi Calling was ON or OFF and if you changed it.",
    "VPN status and Data Saver status (and if you changed them).",
    "Messaging app permissions for storage and sms.",
    "Optional: run_speed_test result.",
    "After any changes, what happens when you try to send a picture message."
  ],
  "reassurance": "You’re very close. If any step is unclear, tell me exactly what you see and I’ll guide you one tap at a time."
}

