  "reassurance": "You’re doing great. Yes—please turn Wi‑Fi OFF next. We’ll do it in tiny steps and I’ll explain why: turning Wi‑Fi OFF forces the phone to use mobile data, which MMS needs while you’re abroad.",
  "step_5_turn_wifi_off": {
    "goal": "Turn Wi‑Fi OFF",
    "how_quick_settings": [
      "Swipe down from the very top of the screen twice to open the full Quick Settings panel.",
      "Find the Wi‑Fi tile. Tap it so it turns gray/off (it may show “Off” or no network name)."
    ],
    "how_settings_menu": [
      "If you prefer the Settings route: Settings > Connections > Wi‑Fi > switch OFF."
    ],
    "tips": [
      "If you still see the classic Wi‑Fi fan icon at the top afterward, it means Wi‑Fi is still on—tap again until it’s off."
    ],
    "what_to_reply": "Please say “Wi‑Fi is OFF” once you’ve done it."
  },
  "after_wifi_off": {
    "goal": "Check the top bar (status bar) icons",
    "what_to_look_for": [
      "Signal bars",
      "A network type like 4G/LTE/5G",
      "A small ‘R’ (for roaming)"
    ],
    "what_to_reply": "Tell me exactly what you see up there now (for example: “3 bars, 4G, and an R”)."
  },
  "step_6_send_test_mms": {
    "when_to_do": "After you confirm what you see in the status bar",
    "how": [
      "Open your Messages app.",
      "Pick one contact.",
      "Attach a small photo (under 1 MB if possible) and send."
    ],
    "what_to_reply": "Tell me if it sends successfully or if you still get “Not sent.”"
  },
  "why_these_steps": "Many phones won’t send MMS over Wi‑Fi, especially while roaming. With Wi‑Fi OFF and roaming/data ON (which we just set up on both the account and phone), MMS should use mobile data and go through.",
  "next_moves_if_needed": "If it still doesn’t send, we’ll check two simple switches next (Wi‑Fi Calling and VPN), and if needed I’ll guide you to reset one network setting safely. I’ll keep it one tap at a time."
}

messages.content:
{
  "why_this_step": "Right now your phone shows 2G, which is too slow for MMS, and a “data disabled” symbol. Before trying a photo, let’s make sure Mobile data is truly ON from the quick toggle. Then we’ll switch your network mode to 4G/5G.",
  "step_1": {
    "goal": "Confirm Mobile data is ON from Quick Settings",
    "how": [
      "Swipe down from the very top of the screen twice to open the full Quick Settings panel.",
      "Find the tile named “Mobile data.” On Samsung it usually looks like two arrows.",
      "If the tile looks gray or says Off, tap it once so it turns blue/On.",
      "If it’s already On, leave it as is (don’t toggle)."
    ],
    "what_to_look_for": [
      "The Mobile data tile should be blue/On.",
      "At the top bar, after a few seconds, you may see a network type like 4G/LTE/5G and possibly a small ‘R’ for roaming."
    ],
    "what_to_reply": "Please reply with “Mobile data tile is ON” and tell me exactly what you see at the top of the screen now (how many bars, 3G/4G/LTE/5G, and if there’s an ‘R’)."
  },
  "preview_next": "Once Mobile data is confirmed ON here, we’ll set your Network mode to 4G/5G in Settings so it doesn’t stay on 2G."
}

