messages.content:
{
  "summary": "You’ve got strong 5G now, so the remaining common blockers for MMS are Wi‑Fi Calling, VPN, or APN/MMSC settings. We’ll take it one tiny step at a time.",
  "step_1_wifi_calling": {
    "goal": "Turn Wi‑Fi Calling OFF (just for this test).",
    "why": "Wi‑Fi Calling can interfere with MMS, especially while abroad. Turning it off is safe and reversible.",
    "how_primary": [
      "Open Settings.",
      "Tap Connections.",
      "Look for Wi‑Fi Calling and turn it OFF (switch grays out)."
    ],
    "how_if_not_found": [
      "If you don’t see it there: open the Phone app (green phone).",
      "Tap the three dots (top‑right) > Settings.",
      "Look for Wi‑Fi Calling and turn it OFF."
    ],
    "what_to_reply": "Please say “Wi‑Fi Calling is OFF” or “I can’t find Wi‑Fi Calling.” I’ll adjust based on what you see."
  },
  "next_after_step_1": {
    "instructions": [
      "Keep Wi‑Fi OFF, Mobile data ON, and Data roaming ON.",
      "Wait about 10 seconds, then try sending that small photo again."
    ],
    "what_to_reply": "Tell me if it sends, or if you still get “Not sent.”"
  },
  "preview_if_still_fails": {
    "step_2_vpn_check": {
      "goal": "Make sure no VPN is connected.",
      "how": [
        "In Settings, use the search bar at the top and type “VPN.”",
        "Tap VPN. If you see a connected VPN, tap it and choose Disconnect.",
        "If there’s no VPN or it’s not connected, that’s okay—just tell me."
      ]
    },
    "step_3_apn_reset": {
      "goal": "Reset APN (network) settings to restore the MMSC for MMS, then reboot.",
      "how": [
        "Settings > Connections > Mobile networks > Access Point Names.",
        "Tap the three dots (top‑right) > Reset to default > confirm.",
        "Then restart your phone (hold Power > Restart).",
        "After the restart, keep Wi‑Fi OFF, confirm 4G/5G shows, and try sending the photo again."
      ]
    }
  },
  "reassurance": "You’re doing great. I’ll wait for your update after Step 1 before moving on. Nothing we’re changing is permanent; we can switch anything back.",
  "question": "Ready to try Step 1 now? If yes, please turn Wi‑Fi Calling OFF and let me know what you find."
}

