  },
  "preview_next_if_needed": {
    "when": "If there was no VPN connected OR it was disconnected and MMS still fails.",
    "step_2_apn_reset": {
      "goal": "Reset APN (network) settings to restore the MMSC for MMS, then reboot.",
      "safety_note": "This only resets carrier network access settings; it won’t erase your photos, apps, or messages.",
      "how": [
