messages.content:
{
  "reassurance": "We’ll proceed carefully, one step at a time.",
  "data_safety": "Resetting APN (Access Point Names) does NOT erase your photos, messages, contacts, or apps. It only restores your carrier’s network settings (including the MMSC needed for MMS). We are NOT doing a full “Reset network settings.”",
  "thought_process": "You have strong 5G with data and roaming ON, Wi‑Fi Calling OFF, and no VPN. The most likely remaining cause is an incorrect or missing MMSC in the APN. Resetting APN to default refreshes those values.",
  "steps": [
    {
      "title": "Open Access Point Names",
      "how": [
        "Settings > Connections > Mobile networks",
        "Tap Access Point Names"
      ],
      "reply_when_done": "Reply with “On APN screen” when you see a list of APNs."
    },
    {
      "title": "Reset APN to default",
      "how": [
        "On the APN screen, tap the three dots (top‑right).",
        "Tap Reset to default, then confirm."
      ],
      "tip": "If you don’t see the three dots, scroll the APN list to the top or bottom—on some models the menu icon appears after a moment.",
      "reply_when_done": "Reply with “APN reset done.”"
    },
    {
      "title": "Restart the phone",
      "how": [
        "Press and hold the Power button (or Power + Volume Down) until the power menu appears.",
        "Tap Restart and confirm."
      ],
      "reply_when_done": "After it restarts, keep Wi‑Fi OFF and confirm you see 4G/5G with signal bars. Reply with what you see (e.g., “5G, full bars”)."
    },
    {
      "title": "Test MMS",
      "how": [
        "With Wi‑Fi OFF, Mobile data ON, and Data roaming ON, open Messages.",
        "Attach a small photo and send."
      ],
      "reply_when_done": "Tell me if it sends or still says “Not sent.”"
    }
  ],
  "next_if_still_fails": {
    "reason": "If MMS still fails after an APN reset and reboot, the messaging app may lack required permissions.",
    "steps": [
      "Settings > Apps > Messages (or Samsung Messages).",
      "Tap Permissions.",
      "Allow permissions for Photos and videos (or Storage/Media) and SMS.",
      "Return to Messages and try sending the photo again (with Wi‑Fi OFF)."
    ],
    "what_to_reply": "Tell me which permissions you enabled and whether the photo sent."
  },
  "question": "Ready to start Step 1? If yes, go to Settings > Connections > Mobile networks > Access Point Names and reply with “On APN screen.”"
}

