messages.content:
{
  "thought_process": "You’ve got strong 5G and the correct APN now. The next most likely blocker is the Messages app not having the needed permissions, or data being restricted by Data Saver. We’ll fix those next, one tiny step at a time.",
  "step_1_permissions": {
    "goal": "Ensure the Messages app has permission to access media and SMS.",
    "why": "MMS needs the app to access photos/videos (media) and SMS/MMS functions.",
    "how": [
      "Open Settings.",
      "Tap Apps.",
      "Find and tap your texting app: “Messages” or “Samsung Messages.” (If you see both, choose the one you normally use to send texts.)",
      "Tap Permissions.",
      "Make sure these are set to Allow:",
      "- Photos and videos (or Files and media / Storage)",
      "- SMS",
      "If there’s a “Phone” permission listed, allow it too."
    ],
    "what_to_reply": "Please say “Permissions allowed” and tell me which ones you enabled."
  },
  "step_2_data_usage_for_messages": {
    "goal": "Make sure the Messages app isn’t restricted by data settings.",
    "why": "If background data is blocked or Data Saver restricts the app, MMS may fail.",
    "how": [
      "Still on the app’s screen, tap Mobile data or Data usage (wording can vary).",
      "Turn ON:",
      "- Allow background data usage",
      "- Allow data usage while Data saver is on (if you see this option)"
    ],
    "what_to_reply": "Please say “App data allowed” once both options are ON, or tell me what you see."
  },
  "step_3_global_data_saver_check": {
    "goal": "Turn off Android’s global Data Saver (if it’s on).",
    "why": "Data Saver can silently block MMS in some setups.",
    "how": [
      "Go to Settings > Connections > Data usage.",
      "Tap Data saver.",
      "If Data saver is ON, turn it OFF."
    ],
    "what_to_reply": "Say “Data Saver is OFF” (or tell me if it was already off)."
  },
  "step_4_test_mms": {
