messages.content:
{
  "summary": "No SIM detected explains why you have No Signal and can’t send MMS. We’ll first identify whether your phone uses a physical SIM or an eSIM, then take the right fix. You didn’t do anything wrong.",
  "what_i_checked_on_our_side": [
    "Your line is active, roaming is enabled, and we added 2 GB of data a moment ago.",
    "Your device supports eSIM. It could be using either a physical SIM or an eSIM profile."
  ],
  "thought_process": "If the phone can’t see a SIM/eSIM, it can’t register on any network. The fix depends on the SIM type: reseat a physical SIM, or re-enable/refresh an eSIM profile.",
  "how_to_tell_physical_vs_esim_on_android": {
    "step_1_quick_physical_check": [
      "Gently remove your phone’s case if you have one.",
      "Look along the phone’s edges for a small tray outline with a tiny pinhole next to it. That’s a physical SIM tray.",
      "If you clearly see this tray, your phone uses (or can use) a physical SIM. If you see no tray at all, you likely use an eSIM."
    ],
    "step_2_in_settings_menu": {
      "goal": "See whether Android shows a Physical SIM slot and/or an eSIM profile.",
      "paths_by_brand": {
        "Samsung": "Settings > Connections > SIM manager",
        "Google Pixel": "Settings > Network & Internet > SIMs",
        "OnePlus": "Settings > Wi‑Fi & network > SIM & network",
        "Other/Generic": "Settings > Network & Internet (or Connections) > SIMs / SIM manager"
      },
      "what_to_look_for": [
        "A section for Physical SIM (SIM 1/SIM 2) and whether it says No SIM.",
        "An eSIM section or an Add eSIM / Download eSIM button.",
        "Your number (555-123-2002) listed with a switch next to it (ON/OFF)."
      ]
    },
    "step_3_dialer_check_safe_read_only": [
      "Open the Phone app and dial *#06# (this does not place a call; it just shows device IDs).",
      "If you see an EID number, your phone supports eSIM. If you see IMEI1/IMEI2 only, that’s normal for dual‑SIM phones; the presence of EID confirms eSIM capability.",
      "Tell me what appears: EID shown or not, and whether it lists any SIM info."
    ]
  },
  "next_steps_based_on_what_you_find": {
    "if_physical_sim_tray_is_present": {
      "reseed_safely": [
        "Power OFF the phone.",
        "Use the SIM eject tool (or a small paperclip) to press into the tray’s pinhole and eject the tray.",
        "Remove the SIM. Gently wipe the gold contacts with a soft, dry cloth.",
        "Reinsert the SIM in the correct orientation (match the notched corner), slide the tray back in.",
        "Power ON, wait 60 seconds, and check for signal bars and a 4G/LTE/5G/3G label."
      ],
      "notes": [
        "This is safe and won’t delete anything.",
        "If it still says No SIM, we can try the SIM in another phone to isolate the issue, and arrange a SIM replacement if needed."
      ]
    },
    "if_esim_is_listed": {
      "enable_refresh": [
        "Settings > SIMs/SIM manager: make sure your eSIM line (your number or carrier name) is ON.",
        "If it’s already ON, toggle it OFF, wait 10 seconds, then ON again.",
        "Ensure Mobile data and Data roaming are ON under the same SIM settings.",
        "Restart the phone, wait 60 seconds, then check for bars and a network label."
      ],
      "if_still_no_sim": "Your eSIM profile may need to be re‑provisioned. I can transfer you to a human agent to push a fresh eSIM to your phone."
    },
    "if_no_tray_and_no_esim_profile_shown": "That usually means there’s no active SIM profile. We’ll need to have a human agent re‑provision an eSIM for your line."
  },
  "reassurance": "All steps above are safe and reversible; they won’t delete photos, messages, or apps. I’ll guide you one step at a time.",
  "questions": [
    "What phone brand/model do you have (Samsung, Google Pixel, OnePlus, etc.)?",
    "Do you see a physical SIM tray on the edge of the phone?",
    "In Settings > SIMs/SIM manager, do you see a Physical SIM section, an eSIM entry, or an Add/Download eSIM option?",
    "When you dial *#06#, do you see an EID listed?"
  ],
  "next_action": "Tell me what you find from the checks above. Based on that, I’ll give you exact, brand‑specific steps to fix it. If it turns out you need a fresh eSIM, I’ll arrange a transfer to a human agent to provision it."
}

